queries.sql:
SELECT TbRIAC.RIACIMPRESO, TbRIAC.RIACFECHA, TbRIAC.RIACTIPO, TbRIAC.RIACMOTIVOCAMBIO
FROM TbRIAC
WHERE (((TbRIAC.IDENTRADA)=336));

SELECT TbEntradas.IDEntrada, TbFichaAnimal.NombreAnimal AS Nombre, TbFichaAnimal.Especie, TbEntradas.NChip, Format([FEntradaProtectora],'dd/mm/yyyy') AS Fentrada, Format([FSalida],'d/mm/yyyy') AS Salida, TbFichaAnimal.Situacion AS Situación
FROM TbFichaAnimal INNER JOIN TbEntradas ON TbFichaAnimal.NCHIP = TbEntradas.NChip
WHERE (((TbEntradas.FEntradaProtectora) Between #8/7/2023# And #8/7/2024#));

SELECT DISTINCT TbAdopcion.NChip, TbFichaAnimal.NombreAnimal
FROM (TbRIAC RIGHT JOIN TbAdopcion ON TbRIAC.IDADOPCION = TbAdopcion.IDAdopcion) LEFT JOIN TbFichaAnimal ON TbAdopcion.NCHIP = TbFichaAnimal.NCHIP
WHERE (((TbRIAC.IDRIAC) Is Null) AND ((TbAdopcion.FAdopcion)>=#1/1/2019#));

SELECT TbFichaAnimal.NCHIP
FROM TbFichaAnimal
WHERE (((TbFichaAnimal.Situacion)='Pendiente de entrada'));

SELECT TbActuacionSanitaria.NCHIP AS CHIP, TbFichaAnimal.NombreAnimal AS Nombre, TbActuacionSanitaria.FechaAnotacion AS [Fecha Vacuna], TbActuacionSanitaria.CodVeterinario AS [Veterinario N], TbActuacionSanitaria.Producto, TbActuacionSanitaria.Lote, 'APAP-ALCALÁ' AS [Propietario Mascota], 'CRTA. PEZUELA KM5,300' AS Dirección, 'OLMEDA DE LAS FUENTES' AS Municipio, 'G28537926' AS [DNI-CIF]
FROM TbActuacionSanitaria INNER JOIN TbFichaAnimal ON TbActuacionSanitaria.NCHIP = TbFichaAnimal.NCHIP
WHERE (((TbActuacionSanitaria.FechaAnotacion) Between [FInicial] And [FFinal]) AND ((TbActuacionSanitaria.CodVeterinario)=1038 Or (TbActuacionSanitaria.CodVeterinario)=6239) AND ((TbActuacionSanitaria.Prueba)='RABIA'));

SELECT TbFichaAnimal.NCHIP, TbFichaAnimal.NombreAnimal, TbFichaAnimal.EutanasiaOtrasCausas, TbFichaAnimal.EutanasiaEnfermedad, TbFichaAnimal.FDefuncion
FROM TbFichaAnimal
WHERE ((Not (TbFichaAnimal.EutanasiaOtrasCausas) Is Null) AND ((TbFichaAnimal.FDefuncion) Is Null)) OR ((Not (TbFichaAnimal.EutanasiaEnfermedad) Is Null) AND ((TbFichaAnimal.FDefuncion) Is Null));

SELECT TbFichaAnimal.NCHIP, TbFichaAnimal.UltimoEstadoAntesDeFallecido
FROM TbFichaAnimal
WHERE ((Not (TbFichaAnimal.FDefuncion) Is Null));

SELECT TbEntradas.IDEntrada, TbEntradas.NChip, TbEntradas.FSalida
FROM (TbEntradas INNER JOIN TbRIAC ON TbEntradas.IDEntrada = TbRIAC.IDENTRADA) INNER JOIN TbAcogidaAnimal ON TbEntradas.NChip = TbAcogidaAnimal.Nchip
WHERE ((Not (TbEntradas.FSalida) Is Null) AND ((TbAcogidaAnimal.FFinal) Is Null));
